static int[] dijkstra(List<int[]>[] g, int n, int src) {
  int[] dist = new int[n];
  Arrays.fill(dist, Integer.MAX_VALUE); dist[src] = 0;
  PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
  pq.add(new int[]{0, src});
  while (!pq.isEmpty()) {
    int[] top = pq.poll(); int d = top[0], u = top[1];
    if (d > dist[u]) continue;
    for (int[] e : g[u]) if (d + e[1] < dist[e[0]]) { dist[e[0]] = d + e[1]; pq.add(new int[]{dist[e[0]], e[0]}); }
  }
  return dist;
}

def cheapest(n, flights, src, dst, k):
    INF = float("inf")
    dist = [INF] * n; dist[src] = 0
    for _ in range(k + 1):
        nxt = dist[:]
        for u, v, w in flights:
            if dist[u] + w < nxt[v]: nxt[v] = dist[u] + w
        dist = nxt
    return -1 if dist[dst] == INF else dist[dst]

def floyd(dist):
    n = len(dist)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist
